function esc(s){ s=String(s==null?'':s); return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function vennSvg(sets){
  if(!Array.isArray(sets)||(sets.length!==2&&sets.length!==3)) return {error:'需 2 或 3 个集合'};
  for(var i=0;i<sets.length;i++){ var s=sets[i]; if(!s||!s.label||!(+s.size>0)) return {error:'每个集合须有 label 与正 size'}; }
  var maxSize=0; sets.forEach(function(s){ if(+s.size>maxSize) maxSize=+s.size; });
  var pal=['#5E6AD2','#10B981','#F5A623'];
  function rr(sz){ return 30 + (+sz/maxSize)*35; }
  function circ(cx,cy,sz,color,label){ return '<circle cx="'+cx+'" cy="'+cy+'" r="'+rr(sz).toFixed(1)+'" fill="'+color+'" fill-opacity="0.42" stroke="'+color+'" stroke-width="1.5"/>'+(label?'<text x="'+cx+'" y="'+(cy+4)+'" text-anchor="middle" font-size="11" fill="#fff">'+esc(label)+'</text>':''); }
  var parts=[];
  if(sets.length===2){ var dx=22; parts.push(circ(70-dx,80,sets[0].size,pal[0],sets[0].label)); parts.push(circ(70+dx,80,sets[1].size,pal[1],sets[1].label)); }
  else { parts.push(circ(80,72,sets[0].size,pal[0],sets[0].label)); parts.push(circ(120,72,sets[1].size,pal[1],sets[1].label)); parts.push(circ(100,108,sets[2].size,pal[2],sets[2].label)); }
  return {svg:'<svg viewBox="0 0 200 160" xmlns="http://www.w3.org/2000/svg" fill-rule="evenodd">'+parts.join('')+'</svg>'};
}
var EXPORTS={vennSvg:vennSvg};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.VennForgePure = EXPORTS; }
